import 'relay/ext_runtime.dart';
import 'session_names_store.dart';

/// The [AgentService] chat surface served by the extension's service-worker
/// agent over a [WorkerRelayTransport] (issue #34 item 1).
///
/// The panel UI keeps its `AgentService` type — everything below the
/// interface seam is relayed instead of local: `sendText` becomes a
/// protocol `prompt` (a `steer` mid-run), the SW's host events
/// (`delta`/`message_done`/`tool_result`/`status`/`error`) rebuild the
/// transcript, and `approval_request` renders through the same approval
/// sheet the local path uses. The UI holds no keys and makes zero provider
/// fetches — the SW owns providers, tools (browser + fs), and the session.
///
/// The local agent loop under the hood is an idle shell: it never runs
/// (see [AgentService.relayBase]); every chat surface member is overridden.
///
/// v1 limits (issue #34): the trajectory ledger stays empty (the panel
/// should hide the tab via `FaChatFeatures`). Approval *mode* is owned by
/// the SW gate: settings snapshots forward it into the local shell (issue
/// #380) so the selector/dialog mirror the real gate, and panel toggles
/// write through via `settings_put`. Attachment staging is NO LONGER one
/// of them (issue #313):
/// `stageAttachment` rides the id-matched `agent.stageUpload` ext_request
/// op into the SW-local sandbox, with the app's exact semantics (shared
/// core helper). Binary-heavy flows (real file pickers with huge files)
/// stay a #34 phase-2 topic; text pastes and normal attachments do not.
final class RelayAgentService extends AgentService {
  RelayAgentService._(this._transport) : super.relayBase() {
    _transport.events.listen(_onTransportEvent);
    unawaited(_transport.connect());
  }

  /// Creates the relay for an extension-hosted panel, or null when this
  /// is not an extension page (plain web — the caller falls back to
  /// [AgentService.create]).
  static Future<RelayAgentService?> create() async {
    final channel = createPortChannel();
    if (channel == null) return null;
    final service = RelayAgentService._(
      detectTransport(portFactory: () => channel, forceOverride: true),
    );
    // Wait (bounded) for the attach + settings snapshot: boot code seeds
    // the provider registry from [swProvider] right after this returns.
    await service.ready;
    return service;
  }

  /// Test seam: drive the relay over a fake channel-backed transport.
  @visibleForTesting
  RelayAgentService.forTest(FaTransport transport) : this._(transport);

  final FaTransport _transport;

  final _messages = <fa_ui.FaChatMessage>[];
  fa_ui.FaChatMessage? _currentAssistant;
  fa_ui.FaChatMessage? _currentThinking;
  bool _running = false;
  String? _error;
  String _modelId = '';
  String _baseUrl = '';
  String _sessionId = '';
  final int _promptSeq = 0;

  /// The panel-side provider registry (persisted providers.json, loaded
  /// at boot): non-null enables the mixed-row connection guard in
  /// [reconfigure] - issue #327 (the relay path skipped the guard the
  /// local service runs; the SW reconfigured blindly).
  ProviderRegistry? providerRegistry;

  /// Id-matched `ext_request` round-trips in flight (staging ops, issue
  /// #313). The SW answers on the SAME channel with an `ext_result`.
  final _pendingExt = <String, Completer<Map<String, dynamic>>>{};
  int _extSeq = 0;

  ApprovalPrompt? _approvalHandler;
  AskCallback? _askHandler;
  RequestSecretCallback? _secretRequestHandler;
  PasswordPromptCallback? _passwordPromptHandler;

  // -- FaChatService ---------------------------------------------------------

  @override
  List<fa_ui.FaChatMessage> get messages => List.unmodifiable(_messages);

  @override
  bool get isStreaming => _running;

  @override
  String? get error => _error;

  @override
  List<String> get pendingSteerTexts => const [];

  /// Panel "New session": the SW archives its live session and starts a
  /// fresh one (`session_new`); the attach trio that answers clears this
  /// side through the normal [AttachedMsg] rebuild (new session id, empty
  /// transcript). A no-op while a turn runs — the SW refuses busy, and
  /// clearing optimistically would blank a transcript that still exists.
  @override
  Future<void> Function()? get newSessionAction => _running
      ? null
      : () async {
          debugPrint('[fah][relay] session_new → SW (new session requested)');
          _transport.newSession();
        };

  /// Panel "open a past session" (`session_open`): the SW archives the
  /// current live session and restores the archive's transcript; the
  /// attach trio rebuilds this side onto it. Same busy rule.
  @override
  Future<void> Function(String sessionId)? get openSessionAction => _running
      ? null
      : (id) async {
          debugPrint('[fah][relay] session_open($id) → SW (switch requested)');
          _transport.openSession(id);
        };

  @override
  String? get liveSessionId => _sessionId.isEmpty ? null : _sessionId;

  /// Fired when the SW's live session changed under us — a
  /// session_new/session_open from ANY surface arrives as an attach
  /// broadcast. The host (main.dart) re-keys the manager's active slot so
  /// active-dots and tile labels follow the real live session.
  void Function(String newSessionId)? onLiveSessionIdChanged;

  /// The SW's session history (live + archives), fetched over
  /// `sessions_query`. Single-flight: overlapping callers share the
  /// in-flight query; `_onProtocolMessage` completes it.
  Completer<List<Map<String, dynamic>>>? _sessionsQuery;

  @override
  Future<List<SessionMetadata>> listSessions() async {
    final inFlight = _sessionsQuery;
    final rows = inFlight != null
        ? await inFlight.future
        : await () async {
            final completer = _sessionsQuery =
                Completer<List<Map<String, dynamic>>>();
            _transport.dispatch(const SessionsQueryMsg());
            try {
              return await completer.future.timeout(
                const Duration(seconds: 10),
                onTimeout: () => const <Map<String, dynamic>>[],
              );
            } finally {
              _sessionsQuery = null;
            }
          }();
    return [
      for (final row in rows)
        SessionMetadata(
          id: row['id'] as String? ?? '',
          createdAt:
              DateTime.tryParse(row['createdAt'] as String? ?? '') ??
              DateTime.fromMillisecondsSinceEpoch(0),
          cwd: row['cwd'] as String? ?? '',
          path: '/session-${row['id'] ?? ''}.jsonl',
          metadata: {
            if (row['archived'] == true) 'archived': true,
            if (row['running'] == true) 'running': true,
          },
        ),
    ];
  }

  @override
  Future<void> sendText(String text) async {
    _error = null;
    // The SW host events carry only the assistant side of the turn, so the
    // user bubble is drawn locally at send time (attach replay does not
    // include it — a known v1 gap after a page reload).
    _append(fa_ui.FaChatMessage(role: 'user', content: text));
    _trajectoryAppend(UserMessage.text(text, timestamp: DateTime.now()));
    _lastUserText = text;
    _pendingEchoes.add(text);
    if (_running) {
      _transport.steer(text);
    } else {
      _transport.sendPrompt(
        'p-${DateTime.now().microsecondsSinceEpoch}-$_promptSeq',
        text,
      );
    }
  }

  @override
  Future<void> sendAttachments({
    required List<fa_ui.FaStagedAttachment> attachments,
    String text = '',
  }) async {
    if (attachments.isEmpty) return sendText(text);
    // A chip staged before an SW restart can point at a file the memory
    // FS already lost (AC4) — verify BEFORE composing, so the composer
    // restores the chips with a clean note instead of sending a
    // silently-empty reference.
    final check = await _extRequest('agent.missingUploads', {
      'paths': [for (final attachment in attachments) attachment.path],
    });
    final missing =
        (check['missing'] as List?)?.cast<String>() ?? const <String>[];
    if (missing.isNotEmpty) {
      throw StateError('staged file lost — re-attach: ${missing.join(', ')}');
    }
    // Same path-reference contract as the app (agent_service.dart): the
    // text names each sandbox path so the agent reads the file with its
    // tools. The v2 prompt is text-only, so image attachments travel as
    // references too — there is no inline-image lane over the relay.
    final fullText = [
      for (final attachment in attachments)
        '[attached file: ${attachment.path} — read it with your tools]',
      if (text.trim().isNotEmpty) text.trim(),
    ].join('\n');
    _error = null;
    _append(fa_ui.FaChatMessage(role: 'user', content: fullText));
    _trajectoryAppend(UserMessage.text(fullText, timestamp: DateTime.now()));
    if (_running) {
      _transport.steer(fullText);
    } else {
      _transport.sendPrompt(
        'p-${DateTime.now().microsecondsSinceEpoch}-$_promptSeq',
        fullText,
      );
    }
  }

  @override
  Future<String> stageAttachment({
    required String name,
    required Uint8List bytes,
  }) async {
    // Pre-check BEFORE the base64 encode (review minor 2): an oversized
    // paste is refused with the SAME shared-core message the SW op would
    // throw, instead of wasting a 4/3 expansion before the refusal.
    if (bytes.length > kMaxStageUploadBytes) {
      throw StateError(stageUploadTooLargeError(bytes.length));
    }
    final result = await _extRequest('agent.stageUpload', {
      'name': name,
      'bytes': base64Encode(bytes),
    });
    final path = result['path'];
    if (path is! String || path.isEmpty) {
      throw StateError('the service worker returned no staged path');
    }
    return path;
  }

  @override
  Future<void> discardStagedAttachment(String path) async {
    if (!path.startsWith('$uploadsDirName/')) return;
    try {
      await _extRequest('agent.discardUpload', {'path': path});
    } on Object {
      // Best effort: a leftover file in uploads/ is harmless.
    }
  }

  /// One-shot id-matched `ext_request` round-trip. Throws [StateError]
  /// with the SW's message on `ok:false`; throws up front while the
  /// transport is not attached (scaffold checkout without sw/agent.js —
  /// the same named refusal the SW's agent-guarded ops give).
  Future<Map<String, dynamic>> _extRequest(
    String op,
    Map<String, dynamic> params,
  ) {
    if (!_transport.isReady) {
      throw StateError('agent not built (missing sw/agent.js)');
    }
    final id = 'ui-${DateTime.now().microsecondsSinceEpoch}-$_extSeq';
    _extSeq += 1;
    final pending = Completer<Map<String, dynamic>>();
    _pendingExt[id] = pending;
    _transport.dispatch(ExtRequestMsg(id: id, op: op, params: params));
    return pending.future;
  }

  @override
  void abort() => _transport.cancel();

  @override
  String transcriptMarkdown() {
    final buffer = StringBuffer();
    for (final message in _messages) {
      buffer
        ..write(_transcriptEntry(message))
        ..writeln();
    }
    return buffer.toString();
  }

  /// The markdown for one transcript row: role header + content for chat
  /// roles, one bullet for tool rows.
  static String _transcriptEntry(fa_ui.FaChatMessage message) {
    switch (message.role) {
      case 'user':
        return '## User\n${message.content}\n';
      case 'tool':
        return '- **${message.toolName ?? 'tool'}**: ${message.content}\n';
      default:
        return '## Assistant\n${message.content}\n';
    }
  }

