  @override
  Stream<TrajectorySnapshot> get trajectory => _trajectoryFeed.stream;

  @override
  void dispose() {
    _trajectoryFeed.dispose();
    super.dispose();
  }

  /// The panel-side trajectory ledger: the SW owns no session-record
  /// chain (its persistence is message-based chrome.storage), so the
  /// panel synthesizes records from the relay rows as they land — the
  /// same data the transcript renders, with the SW's real timestamps.
  final fa_ui.TrajectoryServiceFeed _trajectoryFeed =
      fa_ui.TrajectoryServiceFeed();
  String? _trajectoryLastId;
  int _trajectoryCounter = 0;

  /// Appends one synthesized record to the trajectory ledger, chained
  /// onto the previous row (the builder derives turns from the chain).
  void _trajectoryAppend(Message message) {
    final id = 'relay-${_trajectoryCounter++}';
    _trajectoryFeed.append(
      MessageRecord(
        id: id,
        parentId: _trajectoryLastId,
        timestamp: message.timestamp,
        message: message,
      ),
    );
    _trajectoryLastId = id;
  }

  /// The SW's `timestamp` field (messageToJs), with a receive-time
  /// fallback for rows from an older SW build.
  DateTime _rowTimestamp(Map<String, dynamic> row) =>
      DateTime.tryParse(row['timestamp'] as String? ?? '')?.toLocal() ??
      DateTime.now();

  /// Automatic CodeMie re-authorization — the CLI's proactive SSO restart,
  /// extension edition: an auth-expired turn opens the CodeMie login tab
  /// (the extension shares the browser cookie jar, so a plain tab sign-in
  /// refreshes the credential the SW's fetch carries), polls the jar back
  /// to life, then resends the failed prompt. The user watches the turn
  /// complete instead of babysitting a re-login button.
  bool _codemieReauthInFlight = false;
  String? _lastUserText;

  /// The raw composer texts awaiting their SW-side user message_done —
  /// the echo reconciliation that keeps composer sends single-bubble
  /// while host-initiated mail renders (issue #320). FIFO: several
  /// steers inside one boundary window each match their own SW copy,
  /// so no steered row double-renders.
  final List<String> _pendingEchoes = <String>[];

  /// Test seam: overrides the CodeMie sign-in poll (defaults to the
  /// real [pollCodeMieSignIn] over the extension fetch).
  @visibleForTesting
  static Future<List<String>?> Function({
    required Future<({int status, String body})> Function() probe,
    required void Function() openLoginPage,
  })?
  codemieSignInPollOverride;

  Future<void> _autoReauthCodemie() async {
    if (_codemieReauthInFlight) return;
    _codemieReauthInFlight = true;
    _append(
      fa_ui.FaChatMessage(
        role: 'system',
        content:
            'CodeMie session expired — a browser tab with the CodeMie '
            'login page is opening. Sign in there; the message resends '
            'automatically once the session is back.',
      ),
    );
    notifyListeners();
    try {
      final orgUrl = codeMieOrgUrl(_baseUrl);
      final probeUrl =
          '${codeMieApiBase(orgUrl)}/v1/llm_models?include_all=true';
      // Belt and braces (the caller already checks): a base URL that does
      // not yield an ABSOLUTE probe would resolve against the extension
      // origin and 404 the poll forever.
      if (!(Uri.tryParse(probeUrl)?.hasScheme ?? false)) return;
      final models = await (codemieSignInPollOverride ?? pollCodeMieSignIn)(
        probe: () async {
          final result = await extFetchString(probeUrl);
          // Not an extension host: the auth-expired card stays the
          // manual path — end the poll instead of spinning 5 minutes.
          if (result == null) throw StateError('not an extension host');
          return result;
        },
        openLoginPage: () => unawaited(extOpenTab('$orgUrl/login')),
      );
      if (models == null) {
        _append(
          fa_ui.FaChatMessage(
            role: 'system',
            content:
                'CodeMie re-authorization did not complete — use the '
                'Authorize button on the error above to try again.',
          ),
        );
        return;
      }
      final text = _lastUserText;
      _append(
        fa_ui.FaChatMessage(
          role: 'system',
          content: text != null
              ? 'CodeMie session refreshed — resending your message…'
              : 'CodeMie session refreshed — send your message again.',
        ),
      );
      // Resend straight to the transport: NOT sendText — the original
      // user bubble (and its trajectory record) already exists.
      if (text != null && !_running) {
        _transport.sendPrompt(
          'p-${DateTime.now().microsecondsSinceEpoch}-$_promptSeq',
          text,
        );
      }
    } finally {
      _codemieReauthInFlight = false;
      notifyListeners();
    }
  }

  /// Synthesizes the assistant message one trajectory record wraps: the
  /// relay row carries only text (+ error), so api/provider/usage are
  /// static stand-ins — the ledger renders text, roles and times.
  AssistantMessage _assistantRecord(
    String text, {
    required DateTime timestamp,
    StopReason stopReason = StopReason.stop,
    String? errorMessage,
  }) => AssistantMessage(
    content: [TextContent(text: text)],
    api: 'openai-completions',
    provider: 'relay',
    model: _modelId,
    usage: Usage.zero,
    stopReason: stopReason,
    errorMessage: errorMessage,
    timestamp: timestamp,
  );

  /// User-given session titles, backed by the SW settings channel
  /// (`faSessionNames`): a rename on ANY surface (panel, desktop app,
  /// another tab) round-trips `settings_put` and lands here via the
  /// snapshot broadcast — file-backed stores never saw cross-surface
  /// renames ("renamed to test, reopened — not applied").
  late final SessionNamesStore namesStore = SessionNamesStore.hosted(
    _RelaySessionNamesPersistence(this),
  );

  @override
  SessionNamesStore? get namesStoreOverride => namesStore;

  /// The names half of the last SW settings snapshot.
  Map<String, String> get swSessionNames => {
    if (_lastSwSettings?['faSessionNames'] is Map)
      for (final entry in (_lastSwSettings!['faSessionNames'] as Map).entries)
        if (entry.value is String && (entry.value as String).isNotEmpty)
          '${entry.key}': entry.value as String,
  };

  /// The last full settings snapshot (raw, as broadcast by the SW).
  Map<String, dynamic>? _lastSwSettings;

  /// Persists [names] through `settings_put`: the SW merges per id, so
  /// concurrent renames of DIFFERENT sessions from two surfaces both
  /// survive; ids the snapshot still holds but the writer cleared go out
  /// as empty-string tombstones (the SW merge deletes on empty).
  void putSessionNames(Map<String, String> names) {
    final previous = swSessionNames;
    _transport.dispatch(
      SettingsPutMsg(
        settings: {
          'faSessionNames': {
            ...names,
            for (final id in previous.keys.where(
              (id) => !names.containsKey(id),
            ))
              id: '',
          },
        },
      ),
    );
  }

  // -- FaChatConnection ------------------------------------------------------
  // Reflects the SW connection once its snapshot landed; falls back to the
  // idle local defaults before that (the boot screens render early).

  @override
  String get providerKind =>
      _baseUrl.isNotEmpty ? 'openai-completions' : super.providerKind;

  @override
  String get activeBaseUrl =>
      _baseUrl.isNotEmpty ? _baseUrl : super.activeBaseUrl;

  @override
  String? get activeProviderId => null;

  @override
  String get modelId => _modelId.isNotEmpty ? _modelId : super.modelId;

  /// The SW-side session id (from hello_ack/attached); '' before attached.
  String get relaySessionId => _sessionId;

  Completer<void>? _readyCompleter = Completer<void>();

  /// Completes once the SW handshake landed (attached + first settings
  /// snapshot) so callers seeding UI state read real values. Bounded by
  /// [readyTimeout]; never throws.
  Future<void> get ready {
    final c = _readyCompleter;
    if (c == null) return Future.value();
    return c.future.timeout(
      readyTimeout,
      onTimeout: () {
        debugPrint('[fah][relay] ready TIMEOUT after $readyTimeout');
      },
    );
  }

  static const readyTimeout = Duration(seconds: 5);

  /// The SW's stored provider snapshot (settings_result `faProvider`), or
  /// null before the first snapshot arrives. Seeds the panel's provider
  /// registry so the models screens reflect the SW configuration.
  Map<String, String>? get swProvider =>
      _swProvider == null ? null : Map<String, String>.of(_swProvider!);
  Map<String, String>? _swProvider;

  /// The SW agent's tool state (tools_state), keyed by tool name.
  final _swTools = <String, bool>{};

  // -- transport plumbing ----------------------------------------------------

  void _onTransportEvent(UiTransportEvent event) {
    switch (event) {
      case ProtocolMessageReceived(:final message):
        _onProtocolMessage(message);
      case StateChanged(:final state):
        if (state is TransportReconnecting) {
          _error = 'reconnecting…';
          notifyListeners();
        } else if (state is TransportStreaming && !_running) {
          // Optimistic turn start (sendPrompt flips the link before the
          // SW's status mirror lands). Never CLEARED here: link phases
          // flicker (message_done → attached → tool_result → streaming)
          // across approval/tool waits inside ONE turn, which killed the
          // typing indicator mid-turn — the SW's status events are the
          // turn's ground truth (set/cleared in _onHostEvent).
          _running = true;
          notifyListeners();
        }
      case Dropped():
        _running = false;
        _error = 'extension service worker disconnected';
        // Staging round-trips in flight can never answer now (AC4): fail
        // them so a pending paste surfaces a note instead of hanging.
        for (final pending in _pendingExt.values) {
          if (!pending.isCompleted) {
            pending.completeError(
              StateError('extension service worker disconnected'),
            );
          }
        }
        _pendingExt.clear();
        notifyListeners();
      case Reconnected():
        _error = null;
        notifyListeners();
    }
  }

  /// Protocol-message dispatch, one handler per message type (issue
  /// #486). `UiProtocolMessage` is a sealed family of `final class`es —
  /// the pattern cases are the dispatch table, and an unmapped type (the
  /// UI→SW-only messages, raw hello frames) stays the old no-op.
  void _onProtocolMessage(UiProtocolMessage message) {
    switch (message) {
      case HelloAckMsg(:final sessionId):
        _onHelloAckMsg(sessionId);
      case AttachedMsg(:final sessionId, :final replay):
        _onAttachedMsg(sessionId, replay);
      case MessageDoneMsg(:final message):
        _onMessageDoneMsg(message);
      case ApprovalRequestMsg(:final id, :final call, :final reason):
        unawaited(_decideApproval(id, call, reason));
      case StreamMsg(:final event):
        _onHostEvent(event);
      case SettingsResultMsg(:final settings):
        _onSettingsResultMsg(settings);
      case ToolsStateMsg(:final tools):
        _onToolsStateMsg(tools);
      case SessionsResultMsg(:final sessions):
        _sessionsQuery?.complete(sessions);
      case ExtResultMsg(:final id, :final ok, :final data, :final error):
        _onExtResultMsg(id, ok, data, error);
      case ToolsPutMsg():
        break; // UI -> SW only
      case ErrorMsg(:final message):
        _error = message;
        notifyListeners();
      default:
        break; // hello_ack/attach are the transport's business
    }
  }

  /// Hello (re)syncs after boot, panel reload and SW reconnect. The SW
  /// may have switched its live session while we were gone — a missed
  /// session_new/session_open broadcast leaves hostedLiveId pointing at
  /// a session that renders NOWHERE (the SW excludes the live row from
  /// archives, the slot still holds the old id) and every selection dot
  /// disappears. Re-broadcast like an attach.
  void _onHelloAckMsg(String? sessionId) {
    final previousHello = _sessionId;
    _sessionId = sessionId ?? _sessionId;
    if (sessionId != null &&
        sessionId.isNotEmpty &&
        sessionId != previousHello) {
      onLiveSessionIdChanged?.call(sessionId);
    }
  }

  void _onAttachedMsg(String sessionId, List<Map<String, dynamic>> replay) {
    final previous = _sessionId;
    _sessionId = sessionId;
    _rebuild(replay);
    debugPrint(
      '[fah][relay] attached: session=$sessionId replay=${replay.length}'
      '${previous.isNotEmpty && previous != sessionId ? ' (was $previous)' : ''}',
    );
    if (sessionId.isNotEmpty && sessionId != previous) {
      debugPrint(
        '[fah][relay] live session switched: $previous → $sessionId '
        '(session_new/session_open from this or another surface)',
      );
      onLiveSessionIdChanged?.call(sessionId);
    }
    // Pick up the SW's persisted provider/model (chrome.storage) so the
    // composer reflects reality; reconfigure() writes back the same way.
    _transport.dispatch(const SettingsQueryMsg());
    debugPrint('[fah][relay] settings_query sent');
  }

  void _onMessageDoneMsg(Map<String, dynamic> message) {
    if ((message['role'] as String? ?? 'assistant') == 'user') {
      // Composer sends were echoed locally at sendText time; the
      // matching live row is that echo's SW copy (consume, don't
      // render). A NON-matching row is host-initiated — inbound
      // hub/DAP/bridge mail — and must render at ARRIVAL with the
      // attributed text verbatim (issue #320; it used to be dropped
      // and the mail stayed invisible until a reload).
      final content = _stripTurnContext(message['text'] as String? ?? '');
      // FIFO consume: each steered send matches its own SW copy
      // (several steers may queue inside one boundary window).
      if (_pendingEchoes.remove(content)) {
        return;
      }
      _append(fa_ui.FaChatMessage(role: 'user', content: content));
      _trajectoryAppend(
        UserMessage.text(content, timestamp: _rowTimestamp(message)),
      );
      notifyListeners();
    } else {
      _finishAssistant(message);
    }
  }

  /// Settings snapshots complete `ready` once a live session is attached.
  void _onSettingsResultMsg(Map<String, dynamic> settings) {
    _applySwSettings(settings);
    final c = _readyCompleter;
    if (c != null && !_sessionId.isEmpty) {
      _readyCompleter = null;
      c.complete();
    }
  }

  void _onToolsStateMsg(List<UiToolState> tools) {
    _swTools
      ..clear()
      ..addEntries([for (final t in tools) MapEntry(t.name, t.enabled)]);
    notifyListeners();
  }

  void _onExtResultMsg(
    String id,
    bool ok,
    Map<String, dynamic>? data,
    String? error,
  ) {
    final pending = _pendingExt.remove(id);
    if (pending != null && !pending.isCompleted) {
      ok
          ? pending.complete(data ?? const <String, dynamic>{})
          : pending.completeError(StateError(error ?? 'ext op failed'));
    }
  }

  /// Replays the SW ring after (re)attach: full rebuild, oldest first.
  void _rebuild(List<Map<String, dynamic>> replay) {
    _messages.clear();
    _currentAssistant = null;
    _currentThinking = null;
    _pendingEchoes.clear();
    _pendingMailRow = null;
    // New session, new ledger — replay rows rebuild it record by record.
    _trajectoryFeed.reset();
    _trajectoryLastId = null;
    for (final entry in replay) {
      final event = entry['event'];
      // dartify() (the port transport decodes JS objects) yields
      // Map<Object?, Object?> for NESTED maps — a plain `is
      // Map<String, dynamic>` check silently dropped EVERY row and the
      // panel rendered "No messages yet" against a delivered replay.
      if (event is Map) {
        _onHostEvent(Map<String, dynamic>.from(event), silent: true);
      }
    }
    notifyListeners();
  }

  void _onHostEvent(Map<String, dynamic> event, {bool silent = false}) {
    switch (event['type']) {
      case 'delta':
        _currentAssistant ??= _append(
          fa_ui.FaChatMessage(role: 'assistant', content: ''),
        );
        _currentAssistant!.content += event['text'] as String? ?? '';
      case 'thinking_delta':
        // Reasoning stream from the model: its own collapsible bubble
        // (same shape the local AgentService renders), never merged into
        // the assistant text. A new turn starts a fresh bubble —
        // _finishAssistant clears the current one.
        _currentThinking ??= _append(
          fa_ui.FaChatMessage(role: 'thinking', content: ''),
        );
        _currentThinking!.content += event['text'] as String? ?? '';
      case 'message_done':
        if ((event['role'] as String? ?? 'assistant') == 'user') {
          // The composer echo is reconciled in the live path; replay
          // has no local echo, so the copy is needed there.
          if (silent) {
            final content = _stripTurnContext(event['text'] as String? ?? '');
            _append(fa_ui.FaChatMessage(role: 'user', content: content));
            _trajectoryAppend(
              UserMessage.text(content, timestamp: _rowTimestamp(event)),
            );
          }
        } else {
          _finishAssistant(event, silent: silent);
        }
      case 'tool_result':
        final toolText = event['text'] as String? ?? '';
        final toolName = event['toolName'] as String?;
        final toolIsError = event['isError'] as bool? ?? false;
        _append(
          fa_ui.FaChatMessage(
            role: 'tool',
            content: toolText,
            toolName: toolName,
            isError: toolIsError,
          ),
        );
        _trajectoryAppend(
          ToolResultMessage(
            toolCallId: '',
            toolName: toolName ?? 'tool',
            content: [TextContent(text: toolText)],
            isError: toolIsError,
            timestamp: _rowTimestamp(event),
          ),
        );
      case 'status':
        _running = event['running'] as bool? ?? _running;
        final provider = event['provider'];
        if (provider is Map) {
          _modelId = provider['model'] as String? ?? _modelId;
          _baseUrl = provider['baseUrl'] as String? ?? _baseUrl;
        }
        _syncPendingMail(event['mail']);
      case 'mail_routed':
        // Issue #320 AC4: the session binding re-pointed the live
        // session for inbound mail — say so instead of silently moving
        // the conversation out from under the user.
        _append(
          fa_ui.FaChatMessage(
            role: 'system',
            content:
                'mail from ${event['from']} routed to session '
                '${event['sessionId']}',
          ),
        );
        // Paint NOW — _append alone does not notify, and the notice must
        // not wait for the routed turn's first delta.
        if (!silent) notifyListeners();
      case 'error':
        _error = event['error'] as String? ?? 'unknown relay error';
        _pendingEchoes.clear();
      case 'debug':
        // SW-side diagnostics (provider response/terminal events): the
        // SW console is a separate DevTools window nobody opens, so the
        // lines ride the relay into THIS console — visible next to the
        // [fah][relay] lines when an empty turn needs a cause.
        debugPrint('[fah][sw] ${event['text']}');
    }
    if (!silent) notifyListeners();
  }

  /// Replaces the streaming partial (if any) with the finalized message.
  /// The SW's merged settings snapshot (settings_result): the provider
  /// trio feeds the models screens and the composer.
  void _applySwSettings(Map<String, dynamic> settings) {
    _lastSwSettings = settings;
    // Another surface's renames (or this one's echo) ride the snapshot —
    // sync the hosted names store (no-op when nothing changed).
    namesStore.syncFromSnapshot(swSessionNames);
    // The SW gate OWNS the approval mode: forward it so the mode selector
    // and the approval dialog's yolo checkbox render the real gate state
    // instead of the shell default (issue #380 AC5). Apply silently — a
    // settings_put back would just loop the broadcast.
    final mode = approvalModeFromLabel(settings['faApproval'] as String?);
    if (mode != null && mode != approval.mode) {
      approval.mode = mode;
      notifyListeners();
    }
    final provider = settings['faProvider'];
    debugPrint(
      '[fah][relay] settings snapshot: hasProvider=${provider != null} '
      'keys=${settings.keys.toList()}',
    );
    if (provider is Map) {
      _modelId = '${provider['model'] ?? ''}'.trim();
      _baseUrl = '${provider['baseUrl'] ?? ''}'.trim();
      debugPrint(
        '[fah][relay] snapshot applied: model=$_modelId baseUrl=$_baseUrl',
      );
      _swProvider = {
        'baseUrl': _baseUrl,
        'model': _modelId,
        'apiKey': '${provider['apiKey'] ?? ''}',
      };
      notifyListeners();
    }
  }

  /// The Tools section renders the SW agent's registry, not a local one:
  /// every SW tool is capability-present; the enabled flag is the SW's.
  @override
  Map<String, ResolvedToolAvailability> get toolAvailability => {
    // Host-bound family (issue #327 AC5): the extension never hosts
    // Office.js, so the outlook.* tools render as a gated row with the
    // add-in-only reason instead of staying silent.
    'outlook': const ResolvedToolAvailability(
      enabled: false,
      scope: ToolScope.builtin,
      capabilityPresent: false,
      reason: 'available in the Outlook add-in host only',
    ),
    for (final entry in _swTools.entries)
      entry.key: ResolvedToolAvailability(
        enabled: entry.value,
        scope: ToolScope.builtin,
        capabilityPresent: true,
      ),
  };

  /// Tool toggles travel as `tools_put`; the local map updates
  /// optimistically and the SW's tools_state confirms (or corrects).
  @override
  Future<void> setToolEnabled(String id, bool enabled) async {
    if (!_swTools.containsKey(id) || _swTools[id] == enabled) return;
    _swTools[id] = enabled;
    notifyListeners();
    _transport.dispatch(
      ToolsPutMsg(
        tools: [UiToolState(name: id, enabled: enabled)],
      ),
    );
  }

  /// Settings save from the panel UI goes over the wire as `settings_put`:
  /// the SW persists it to chrome.storage and reconfigures its agent. The
  /// local (idle) agent is deliberately never touched — the panel holds no
  /// provider state of its own in extension mode.
  ///
  /// gh-1044 I1: the same add-provider-flow refusal the base implements —
  /// a restore-shaped `settings_put` is dropped while an add flow is
  /// latched; the flow's own switch (`fromProviderAddFlow`) goes through.
  @override
  Future<void> reconfigure(
    AgentConfig config, {
    bool fromProviderAddFlow = false,
  }) async {
    // The shared predicate (the base owns the refusal rule — one shape,
    // no drift); only the log prefix differs.
    if (reconfigureRefusedByAddFlow(fromProviderAddFlow)) {
      debugPrint(
        '[fah][relay] reconfigure refused: a provider add flow is in '
        'progress — the active connection stays untouched until it finishes',
      );
      return;
    }
    // Issue #327: the same guard the local service runs in reconfigure -
    // the relay override dispatched settings_put blindly (the exact
    // surface where an OpenRouter-format model id rode a CodeMie
    // connection). Refuse BEFORE the SW ever sees the connection.
    final problem = providerConnectionProblem(
      providerRegistry,
      config,
      extensionHost: isExtensionHost(),
    );
    if (problem != null) {
      debugPrint('[fah][relay] reconfigure refused: $problem');
      _error = problem;
      notifyListeners();
      throw ProviderConnectionException(problem);
    }
    debugPrint(
      '[fah][relay] reconfigure -> settings_put: '
      'baseUrl=${config.baseUrl} model=${config.modelId} '
      'key.len=${config.apiKey.length}',
    );
    _modelId = config.modelId;
    _baseUrl = config.baseUrl;
    final k = config.apiKey;
    _transport.dispatch(
      SettingsPutMsg(
        settings: {
          'faProvider': {
            'baseUrl': config.baseUrl,
            'apiKey': k,
            'model': config.modelId,
          },
        },
      ),
    );
    notifyListeners();
  }

  void _finishAssistant(Map<String, dynamic> message, {bool silent = false}) {
    final role = message['role'] as String? ?? 'assistant';
    final text = message['text'] as String? ?? '';
    debugPrint('[fah][relay] message_done role=$role len=${text.length}');
    // The streaming partial is replaced by the finalized message.
    final partial = _currentAssistant;
    if (partial != null) _messages.remove(partial);
    _currentAssistant = null;
    // The finished thinking bubble stays on screen; the next turn's
    // reasoning opens a fresh one.
    _currentThinking = null;
    // An errored turn (expired SSO session, gateway failure) carries its
    // message in the `error` field with an EMPTY text — surface it as an
    // error bubble (the [[auth-expired:…]] marker renders the
    // re-authorize card), never as the "empty response" placeholder.
    final errorText = message['error'] as String?;
    if (role == 'assistant' && errorText != null && errorText.isNotEmpty) {
      _append(
        fa_ui.FaChatMessage(
          role: 'assistant',
          content: errorText,
          isError: true,
        ),
      );
      _trajectoryAppend(
        _assistantRecord(
          errorText,
          timestamp: _rowTimestamp(message),
          stopReason: StopReason.error,
          errorMessage: errorText,
        ),
      );
      // The CLI restarts CodeMie SSO the moment the saved cookie is
      // expired; the extension does the same reactively — open the login
      // tab and resend, no manual Authorize click needed. LIVE failures
      // only: a replayed historical error row must not fire the flow at
      // every boot (and `_baseUrl` may still be empty before the settings
      // snapshot lands — a relative probe URL then resolves against the
      // extension origin and 404s forever).
      if (!silent &&
          authExpiredProvider(errorText) == 'codemie' &&
          (Uri.tryParse(_baseUrl)?.hasScheme ?? false)) {
        unawaited(_autoReauthCodemie());
      }
      notifyListeners();
      return;
    }
    if (role == 'assistant' && text.isEmpty) {
      // A tool-call-only assistant turn legitimately has no text — the
      // tool_result rows that follow tell the story; a placeholder here
      // reads like a failure mid-flow (the approval dialog opens while
      // the empty bubble is already on screen).
      final toolCalls = message['toolCalls'];
      final hasToolCalls = toolCalls is List && toolCalls.isNotEmpty;
      if (!hasToolCalls) {
        _append(
          fa_ui.FaChatMessage(
            content: fa_ui.emptyResponsePlaceholder,
            role: 'assistant',
          ),
        );
      }
    } else if (role == 'tool') {
      _append(
        fa_ui.FaChatMessage(
          role: 'tool',
          content: text,
          toolName: message['toolName'] as String?,
        ),
      );
    } else if (role == 'assistant' && text.isNotEmpty) {
      _append(fa_ui.FaChatMessage(role: role, content: text));
      _trajectoryAppend(
        _assistantRecord(text, timestamp: _rowTimestamp(message)),
      );
    } else {
      _append(fa_ui.FaChatMessage(role: role, content: text));
    }
    notifyListeners();
  }

  fa_ui.FaChatMessage _append(fa_ui.FaChatMessage message) {
    _messages.add(message);
    return message;
  }

  /// The mid-run mail indicator (issue #320 AC3): one system row while
  /// inbound mail waits for the next step boundary, removed on the
  /// drain refresh that delivers it.
  fa_ui.FaChatMessage? _pendingMailRow;

  void _syncPendingMail(Object? mail) {
    final map = mail is Map ? mail : null;
    final pending = (map?['pending'] as num?)?.toInt() ?? 0;
    if (pending <= 0) {
      if (_pendingMailRow != null) {
        _messages.remove(_pendingMailRow);
        _pendingMailRow = null;
        notifyListeners();
      }
      return;
    }
    final senders = {
      for (final s in map?['senders'] as List? ?? const []) '$s',
    }.join(', ');
    final text =
        '$pending queued message${pending == 1 ? '' : 's'} from '
        '$senders — will land at the next step boundary';
    if (_pendingMailRow != null) {
      _pendingMailRow!.content = text;
    } else {
      _pendingMailRow = _append(
        fa_ui.FaChatMessage(role: 'system', content: text),
      );
    }
    notifyListeners();
  }

  /// Replay/live rows carry the SW's per-turn `[context] …` header; it
  /// is plumbing, not conversation — strip it for display and matching.
  static String _stripTurnContext(String raw) {
    final at = raw.indexOf('\n');
    return raw.startsWith('[context] ') && at > 0 ? raw.substring(at + 1) : raw;
  }

  Future<void> _decideApproval(
    String id,
    Map<String, dynamic> call,
    String reason,
  ) async {
    final handler = _approvalHandler;
    if (handler == null) {
      // No UI mounted: stay silent. The decision belongs to a surface that
      // can actually ask the human — another panel client (or the e2e
      // driver) may answer; the SW's 120s timeout is the conservative
      // backstop and denies with a note if nobody does. An instant deny
      // here once raced ahead of the real UI and recorded a denial the
      // user never chose.
      debugPrint(
        '[fah][relay] approval id=$id has no handler — leaving it unanswered',
      );
      return;
    }
    final summary = call['toolName'] as String? ?? 'tool';
    debugPrint('[fah][relay] approval dialog open id=$id tool=$summary');
    late final ApprovalDecision decision;
    try {
      decision = await handler(
        ApprovalRequest(
          toolName: summary,
          tier: ApprovalTier.exec,
          arguments: call,
          reason: reason,
        ),
      );
    } on Object catch (error) {
      // The surface owes an answer, but the caller is unawaited — a
      // rethrow would vanish into an unhandled async error. Log and deny.
      debugPrint(
        '[fah][relay] approval handler threw: $error — denying id=$id',
      );
      _transport.dispatch(ApprovalResponseMsg(id: id, decision: 'deny'));
      return;
    }
    debugPrint('[fah][relay] approval answered id=$id decision=$decision');
    _transport.dispatch(
      ApprovalResponseMsg(
        id: id,
        decision: decision == ApprovalDecision.deny ? 'deny' : 'allow',
      ),
    );
  }
}

/// [SessionNamesPersistence] over the relay's settings channel: reads the
/// names half of the last SW snapshot, writes through `settings_put`.
final class _RelaySessionNamesPersistence implements SessionNamesPersistence {
  _RelaySessionNamesPersistence(this._service);

  final RelayAgentService _service;

  @override
  Map<String, String> read() => _service.swSessionNames;

  @override
  Future<void> write(Map<String, String> names) async =>
      _service.putSessionNames(names);
}

